const CANDIDATES = [{"id": 1, "name": "Pawn Forfeiture Flow Meter", "vol": "I", "score": 23, "lens": "Vice, luxury & status consumption", "data": "Live listing counts, category mix, and new-arrival velocity on EZPAWN's aggregated online catalog (shop.ezpawn.com, pooling 500+ stores) and the eBay stores run by large pawn operators (e.g., ebay.com/str/ezpawncorp), which surface forfeited collateral for sale.", "collection": "Daily scrape of shop.ezpawn.com category pages (Shopify-style, trivially parseable) counting new SKUs in gold/jewelry, watches, tools, and electronics; poll pawn eBay stores via the eBay Browse API for listing counts and start prices. Rising new-listing velocity equals rising loan defaults/forfeitures ~90 days earlier.", "trade": "Long FirstCash (FCFS) and EZCORP (EZPW) over 2-6 weeks into earnings when forfeiture flow and gold-heavy mix accelerate (pawn margins fatten in consumer stress); the same series doubles as a short-consumer overlay (XRT puts).", "mechanism": "A pawn listing appears online only after a borrower fails to redeem, so aggregate listing velocity is a direct, dated census of subprime household default on secured micro-loans \u2014 it leads both the pawn operators' own segment profits and broader delinquency statistics by the redemption-window lag.", "edge": "EZPW/FCFS are small caps with skeletal coverage; the operators helpfully centralized their own exhaust into one scrapeable storefront and nobody appears to time-series it.", "risk": "Listing cadence partly reflects store staffing and merchandising pushes rather than defaults, and gold-price rallies independently swell jewelry forfeiture values."}, {"id": 2, "name": "Screwworm Frontline Bulletin Watch", "vol": "I", "score": 22, "lens": "Health & biology signals", "data": "Spanish-language zoosanitary alerts from Mexico's SENASICA, COPEG (Panama-US screwworm commission) sterile-fly dispersal reports, and USDA APHIS stakeholder notices on New World screwworm detections moving north.", "collection": "Scrape SENASICA's press/alert pages and state-level Mexican ag bulletins daily with a Spanish NLP filter for 'gusano barrenador' detections by municipality, plus COPEG dispersal stats and the APHIS stakeholder-registry emails; geocode detections against the US border and cattle-import crossings.", "trade": "Long feeder cattle futures (GF) and GF/LE spreads within hours of a new northward detection, anticipating renewed US suspension of Mexican feeder imports (~1M head/year); hold days to weeks through the official closure announcement.", "mechanism": "US border closures to Mexican cattle are triggered by detection geography, so each confirmed northward case mechanically raises the probability of an import halt that removes a meaningful slice of feeder supply \u2014 a chokepoint where futures repriced sharply during the 2025 closures.", "edge": "The originating documents are Spanish-language veterinary bulletins that post before English wire coverage or USDA statements; US ag desks systematically under-monitor Mexican agency websites.", "risk": "Closure decisions are discretionary and political, so a detection may not trigger action; the market has partially learned the pattern since 2025, compressing the reaction window."}, {"id": 3, "name": "Lock Queue (Army Corps LPMS outage telemetry)", "vol": "I", "score": 21, "lens": "Physical-world sensing & sensor exhaust", "data": "The Army Corps' Lock Performance Monitoring System and public Lock Status/Queue reports show near-real-time operational status, stall events, and the number of tows waiting at every Mississippi, Illinois, and Ohio River lock.", "collection": "Poll the USACE LPMS/Corps Locks public web endpoints hourly for chokepoint locks (Lock 25, LaGrange, Olmsted), alerting on unscheduled outages and queue counts above seasonal norms during the fall export program.", "trade": "CBOT corn and soybean futures and calendar spreads, plus ADM and MOS equity, over days to three weeks when a chokepoint lock fails during harvest export season.", "mechanism": "Roughly 60% of US grain exports funnel through this one river system to NOLA; a stalled lock strands barge tows, collapses interior basis, delays export inspections, and forces futures spread repricing - a classic convex chokepoint response.", "edge": "It is a bureaucratic government telemetry system with an interface nobody wires into intraday trading; ag desks react to the same outages days later via USDA transport reports and newswires.", "risk": "Major failures get publicized fast, shrinking the window to hours in the worst cases; and barge traffic can reroute or wait out short outages, so only multi-day failures at true chokepoints are tradable."}, {"id": 4, "name": "German Tank Checkout", "vol": "I", "score": 21, "lens": "Human digital-behavior exhaust", "data": "Sequential order/invoice numbers embedded in e-commerce order confirmations of direct-to-consumer public companies.", "collection": "Place (then cancel or return) minimal-value orders weekly at targets like Revolve, Figs, Allbirds, and 1-800-Flowers; record the order IDs from confirmation emails/pages, and treat the week-over-week ID delta as total orders placed, per the WWII German tank estimator.", "trade": "Long/short the single names (RVLV, FIGS, BIRD, FLWS) into earnings on a 2-6 week horizon when implied order-count growth diverges materially from consensus revenue.", "mechanism": "The order counter is the company's own transaction ledger leaking one scalar per observation; order count times a stable average order value is revenue, observed weeks before the print with essentially zero sampling error.", "edge": "It is absurdly manual, per-company, and requires actually transacting, so no data vendor can package it and no fund will staff it, yet it costs a few sample orders a week.", "risk": "Companies switch to non-sequential IDs (Shopify now obfuscates by default), and cancellations, returns, and AOV mix shifts distort the order-to-revenue mapping; repeated probe orders may violate terms of service."}, {"id": 5, "name": "Store-Leader Posting Geocoder", "vol": "I", "score": 21, "lens": "Labor-market micro-signals", "data": "General-manager and store-leader job postings on the career sites of high-multiple unit-growth restaurant and retail chains, which contain the street addresses of not-yet-announced locations months before opening.", "collection": "Weekly scrape of ATS feeds for CAVA, BROS, WING, SG, CMG, DNUT and similar; regex/geocode location fields, dedupe against known open stores from the brands' own store-locator APIs, and count net-new addresses as a real-time unit-pipeline tracker.", "trade": "2-6 week horizon into quarterly prints: pipeline running ahead of the company's stated unit-growth guidance \u2192 long stock or calls into earnings; a stalling new-address count at a story stock priced for 15%+ unit growth \u2192 short into the print.", "mechanism": "These stocks are valued almost entirely on unit-growth trajectory; a GM must be hired 2-4 months pre-opening, so the address-bearing posting is a mechanical leading indicator of the exact KPI (openings this quarter, forward pipeline) that drives the earnings reaction.", "edge": "Posting-count vendors aggregate volumes but discard the address payload; extracting and deduplicating physical locations is bespoke per-company work on a universe of a dozen mid-caps \u2014 ideal for an individual, uneconomic for a data vendor.", "risk": "Some chains hire GMs from internal benches without posting, undercounting the pipeline; companies can strip addresses from postings ('Dallas area') once they notice, degrading precision."}, {"id": 6, "name": "Heat-Dome Miner Curtailment Credits", "vol": "I", "score": 21, "lens": "Climate second-order effects", "data": "ERCOT public real-time prices, demand-response deployments, and 4CP peak intervals during Texas heat waves, mapped to Bitcoin miners (RIOT, CIFR, WULF) whose economics include large power-curtailment credits disclosed only in monthly production updates.", "collection": "Pull ERCOT real-time LMPs and load data from the public API, model each miner's curtailment decision (hash price vs power price at its known nodes, e.g. Riot's Rockdale/Corsicana), and estimate accrued power credits and lost BTC production daily during heat events.", "trade": "Trade RIOT/CIFR options or shares into their first-business-day-of-month production updates (1-3 week horizon), long when modeled curtailment credits exceed the naive hashrate-based BTC estimate that crypto analysts publish, short the reverse.", "mechanism": "Texas heat domes push ERCOT prices past miners' breakeven, and miners sell power back or collect demand-response credits worth tens of millions in a hot month (Riot's August 2023 credits exceeded its mining revenue); the entire calculation is reproducible from public grid data before the company dis", "edge": "Crypto-equity investors model hashrate and BTC price, power traders don't cover mining stocks \u2014 the signal lives exactly in the gap between two analyst communities, and the accounting item (power credits) is dismissed as one-off noise.", "risk": "The signal is regime-dependent: mild summers, changes to ERCOT demand-response programs, or miners pivoting capacity to AI hosting contracts would shrink the curtailment-credit lever and the surprise it generates."}, {"id": 7, "name": "Sphere Occupancy Cam", "vol": "I", "score": 21, "lens": "Media, entertainment & attention markets", "data": "Continuous public webcam and 24/7 YouTube live-stream views of the Las Vegas Sphere's exterior LED (the Exosphere), whose paid advertising is literally visible from the street.", "collection": "Sample frames every few minutes from strip cams, classify content with a small vision model into paid third-party ads vs house/event promo vs dark, and build a paid-ad-hours index; supplement with a scrape of Sphere's event calendar for show counts and residency adds.", "trade": "SPHR shares and options into quarterly earnings on a 2-8 week horizon, long when paid-ad occupancy and event density inflect above prior-quarter run-rate, short when the board fills with house promo.", "mechanism": "Exosphere advertising and event count are the company's two revenue engines and disclosure is quarterly; ad occupancy measured off a webcam is ground truth for the advertising line, the same way tank shadows were for oil storage.", "edge": "It is a one-ticker signal that looks like a stunt \u2014 watching a giant ball on a webcam \u2014 so no institutional data vendor will productize it, but the revenue base is small enough that visible occupancy swings are material.", "risk": "Single-name idiosyncrasy (Dolan governance headlines) can swamp fundamentals, and undisclosed ad pricing means occupancy maps imperfectly to dollars; camera angles and stream availability change."}, {"id": 8, "name": "FECM Export-Order Sniper", "vol": "II", "score": 21, "lens": "Disclosure-latency arbitrage", "data": "The Department of Energy's Office of Fossil Energy and Carbon Management docket pages, where LNG export authorizations, extension orders, and permit actions for specific terminals post before company press releases or wire coverage.", "collection": "Scrape the DOE FECM LNG export docket index (energy.gov/fecm LNG regulatory docket pages and the linked regulations.gov dockets) hourly for new orders and filings, matching docket numbers to terminals and sponsors (Venture Global, Cheniere, NextDecade, Sempra's Port Arthur, plus feedgas suppliers like EQT).", "trade": "Trade the sponsor equity and options within hours of an order posting (long on grants/extensions, short on denials or remands), and express the macro leg in Henry Hub natural gas futures calendar spreads over days as new export demand gets priced.", "mechanism": "Non-FTA export authorization is the binding gate on multi-billion-dollar terminal FIDs; the signed order is public the moment DOE dockets it, but companies confirm on their own IR schedule, so the docket leads the stock's information set by hours to days.", "edge": "It is a genuinely obscure administrative docket with irregular posting times \u2014 post-export-pause, order timing became political and unpredictable, which raised the value of watching the primary source while most investors wait for headlines.", "risk": "Politically salient orders sometimes leak to trade press or get teased by officials first, and gas macro can swamp the single-name move; denial events are rare so the short side barely exists."}, {"id": 9, "name": "OIR Cat Data-Call Tape", "vol": "II", "score": 21, "lens": "Disclosure-latency arbitrage", "data": "The Florida Office of Insurance Regulation's catastrophe reporting data calls, which after a hurricane landfall publish claims counts, paid and case-incurred losses by line of business on a set update cadence \u2014 weeks before insurers publish their own loss estimates in 8-Ks.", "collection": "Scrape the FLOIR catastrophe reporting page (floir.com) after each named-storm event for every scheduled data-call update, track the trajectory of claims counts and incurred losses against prior storms' curves, and where per-company breakdowns are published, map writers to tickers.", "trade": "Trade Florida-concentrated insurers (UVE, HCI, HRTG, SLDE) and quota-share-exposed reinsurers (RNR, ACGL) long or short over 1-3 weeks, positioning when the data-call loss trajectory runs materially above or below what the stocks' post-storm selloff implies.", "mechanism": "The regulator's mandatory data call aggregates the same claims data insurers will eventually disclose, but publishes it on the state's schedule rather than the companies' \u2014 so the developing industry loss is public while individual stocks still trade on landfall-day guesses.", "edge": "It is a single state agency webpage with no API, updated irregularly per event \u2014 institutional cat modelers focus on their own vendor estimates (RMS/Verisk ranges) and largely ignore the regulator's actual claims tape.", "risk": "Aggregated data can hide which company bears the loss, and reinsurance attachment points make the mapping from industry incurred to per-name EPS nonlinear; a mis-set reserve trajectory early in the data call can whipsaw the read."}, {"id": 10, "name": "Royalty Drip Nowcast", "vol": "II", "score": 21, "lens": "Structured-finance small print", "data": "Quarterly (and in some deals monthly) noteholder reports of whole-business securitizations \u2014 Wingstop Funding, Jack in the Box Funding, Wendy's Funding, Driven Brands Funding, Planet Fitness (Planet Fitness Master Issuer) \u2014 which disclose retained collections, royalty receipts, and system-wide sales", "collection": "Register as an investor on the trustee portals (Citibank Agency & Trust's sf.citidirect, UMB, Computershare CTSLink) to download noteholder reports; supplement with KBRA and S&P surveillance releases that quote DSCR and trailing system sales, and with TRACE dissemination of the 144A notes for a price cross-check.", "trade": "Long/short WING, JACK, WEN, DRVN, PLNT equity and short-dated options into earnings: royalty collections divided by the contractual royalty rate arithmetically equals system-wide sales for the securitized perimeter, giving a same-store-sales estimate before the company reports. Horizon: 1-3 weeks pr", "mechanism": "The securitization's waterfall is fed directly by franchisee royalty remittances, so the trustee report is an audited-grade cash register for the entire system; when disclosed collections diverge from consensus SSS, the earnings surprise is nearly mechanical because the same cash feeds both document", "edge": "These reports exist for bond investors who hold-to-maturity and never talk to equity desks; equity analysts model SSS from foot-traffic panels while the actual cash figure sits in a PDF on a trustee portal that requires a tedious one-time registratio", "risk": "Report timing sometimes lands after the earnings date for a given quarter, and new-store openings versus closures inside/outside the securitized perimeter can distort the collections-to-SSS mapping; trustee portals may also tighten access to holders "}, {"id": 11, "name": "Upgrade-Wave Telemetry", "vol": "II", "score": 21, "lens": "Structured-finance small print", "data": "Verizon Master Trust device-payment-plan ABS: public monthly 10-D filings on EDGAR disclosing prepayment and upgrade rates on millions of handset installment loans \u2014 a direct census of how fast US consumers are trading in phones.", "collection": "Parse Verizon Master Trust (and similar T-Mobile US Trust filings where public) monthly 10-Ds from EDGAR \u2014 small structured tables, trivially scraped \u2014 and build an upgrade-prepayment index with seasonal adjustment around September launch cycles.", "trade": "Trade AAPL (and suppliers like SWKS, QRVO, CRUS) around launch-quarter earnings: an above-trend upgrade-prepayment wave in Oct-Dec 10-Ds confirms a strong iPhone cycle weeks before Apple's January print; also trade VZ/TMO on delinquency inflections in the same files. Horizon: 2-4 weeks pre-earnings.", "mechanism": "A handset upgrade at a carrier mechanically prepays the old installment loan into the ABS trust, so trust prepayment speed is a high-coverage, hard-accounting proxy for US iPhone unit velocity \u2014 the metric Apple stopped disclosing \u2014 and delinquency on $30/month phone loans is among the earliest cons", "edge": "Telco ABS is followed by a handful of securitized-credit analysts who care about note enhancement, not Apple units; the equity crowd uses IDC/wafer checks and never reads the trust's monthly prepayment table sitting free on EDGAR.", "risk": "Carrier promo policy (aggressive trade-in subsidies) can swing upgrade rates independently of true demand, and the trusts' revolving structure means Verizon's collateral-addition choices can distort measured speeds."}, {"id": 12, "name": "Import Alert Ambush", "vol": "I", "score": 20, "lens": "Legal & regulatory breadcrumbs", "data": "FDA Import Alerts (e.g., Alert 66-40 for drug GMP violations) and the monthly OASIS Import Refusal Report, which list foreign plants whose shipments are detained without physical examination.", "collection": "Scrape the FDA import alert pages (accessdata.fda.gov/cms_ia) daily and diff the firm lists; join new plant additions to the FDA Drug Establishment registration database and to public filings mapping plants to companies (Dr. Reddy's, Sun Pharma, Aurobindo, Cipla ADRs and their US customers).", "trade": "Short the affected generic maker's US-listed ADR (or long its closest competitor on the same molecules) within hours of a plant being added; hold days to two weeks until the warning letter or news coverage catches up. Long US-listed rivals like Amphastar or Hikma when a competing plant is detained.", "mechanism": "An import alert legally blocks a plant's US shipments immediately, cutting revenue on every ANDA sourced there weeks before the company 8-K, the warning letter posting, or sell-side notes; the alert page is the first public artifact of the enforcement action.", "edge": "Import alerts are updated on obscure static HTML pages with no feed or notification service, coverage is dominated by trade press (Pharma niche outlets) with multi-day lag, and mapping plant names to tickers requires tedious manual curation nobody ha", "risk": "Many alert additions involve plants immaterial to the parent's revenue, so mis-mapping plant-to-product exposure produces false positives; FDA occasionally posts additions with erratic lag, eroding the latency advantage."}, {"id": 13, "name": "CBER Flu-Lot Release Ledger", "vol": "I", "score": 20, "lens": "Health & biology signals", "data": "FDA CBER's seasonal influenza vaccine lot-release page, which publishes weekly cumulative doses released by manufacturer during the August-December distribution season.", "collection": "Scrape the FDA.gov influenza-season lot-release table weekly (archive.org for prior-season baselines); track cumulative dose pace and mix for Sanofi (Fluzone), GSK (Flulaval/Fluarix), and CSL Seqirus versus the same week in prior years.", "trade": "SNY and GSK ADRs (and CSL.AX) into Q3 earnings over 2-8 weeks: long the manufacturer running ahead of prior-year release pace against consensus flu-franchise numbers, short on evident lot-release stalls that signal manufacturing or demand problems.", "mechanism": "Flu vaccine revenue is recognized on shipment and concentrated in one quarter, and doses cannot ship until CBER releases the lots \u2014 so the weekly release ledger is an almost mechanical shipment nowcast that precedes the quarterly disclosure analysts wait for.", "edge": "The page is an obscure regulatory artifact maintained for public-health transparency; pharma analysts discuss flu-season demand qualitatively but almost none track the weekly lot ledger quantitatively.", "risk": "Lot release timing can diverge from actual shipments and pricing, and the flu franchise is a modest slice of these diversified majors, diluting the tradable beta."}, {"id": 14, "name": "Embargo Clock", "vol": "I", "score": 20, "lens": "Media, entertainment & attention markets", "data": "Review-embargo lift timing for wide theatrical releases \u2014 when the Rotten Tomatoes score goes live relative to release day, plus embargo dates leaked via critic tweets and trade newsletters.", "collection": "Poll each upcoming title's Rotten Tomatoes page hourly to timestamp the first-review drop; maintain an embargo calendar scraped from critic accounts on X/Bluesky and newsletters like The InSneider. Score each release on embargo-lead-time vs the studio's own historical norm.", "trade": "When a tentpole's embargo lifts under 48 hours before release, buy puts on IMAX/CNK/NCMI or the distributor and sell Kalshi Rotten-Tomatoes-score and box-office contracts; 2-10 day horizon through opening weekend.", "mechanism": "Studios set late embargoes precisely when test screenings are bad \u2014 it is a costly, self-revealing act of concealment that precedes both the reviews and the grosses, so embargo timing predicts the box-office miss before any public quality signal exists.", "edge": "Embargo timing is inside-baseball folklore among film journalists that has never been quantified into a time-stamped dataset; there is no vendor for it and it looks too soft to be data.", "risk": "Critic-proof franchises open big despite hidden reviews, and studios could deliberately randomize embargo policy if the tell becomes public; sample size per year is small."}, {"id": 15, "name": "Depot Watch", "vol": "I", "score": 20, "lens": "Media, entertainment & attention markets", "data": "SteamDB's public change-log of Steam builds, depots, branches, regional price rows, and rating metadata for major unreleased games (GTA VI's companion apps, EA/Ubisoft/CDPR titles).", "collection": "Poll SteamDB and the Steam Web API for tracked app IDs: new preload depots, branch names like 'release_candidate', certification-style build cadence, ratings-board rows, and price-row creation, each timestamped.", "trade": "Options on TTWO, EA, UBI.PA, CDR.WA, KRAFTON around release-date confirmation or delay windows; days-to-weeks. TTWO is the flagship: single-title timing news moves it mid-to-high single digits.", "mechanism": "Launch logistics are mechanical \u2014 preload depots and RC branches must appear before a date is real, and their absence inside the required window reveals a slip before the press release; for publishers whose DCF is one title, timing IS the stock.", "edge": "SteamDB is watched by gamers for fun and leaks, not mapped to tickers or option expiries; no vendor packages build telemetry for funds, and interpreting depot semantics requires niche platform literacy.", "risk": "Console-first titles bypass Steam entirely, and publishers push dummy or obfuscated builds, generating false positives; Valve could hide change metadata."}, {"id": 16, "name": "Preorder Counter Arb", "vol": "I", "score": 20, "lens": "Media, entertainment & attention markets", "data": "Live K-pop album preorder tallies published on fan-commerce retailers \u2014 Ktown4u posts running cumulative preorder counters per release \u2014 plus Hanteo/Circle first-week sales charts.", "collection": "Scrape Ktown4u event pages and Weverse Shop listings hourly during preorder windows for HYBE/SM/JYP/YG comebacks, benchmark the preorder curve against the same artist's previous cycle, and predict the first-week Hanteo print.", "trade": "Long/short HYBE (352820.KS), SM (041510.KQ), JYP (035900.KQ), YG (122870.KQ) via KRX access (available through IBKR) over the 1-4 week comeback window into the first-week sales print that Korean retail and sell-side trade on.", "mechanism": "First-week album sales are the acknowledged KPI for these stocks, and the preorder counters are a public running total of that exact number weeks early \u2014 a scheduled surprise nowcast where the proxy is literally a partial sum of the target.", "edge": "The data lives on Korean-language fan-commerce pages and is compiled manually by stan Twitter accounts, not vendors; Western funds rarely touch KOSDAQ entertainment names despite their liquidity.", "risk": "Retailer mix shifts (bulk Chinese fan-union orders landing late, direct Weverse exclusives) break the counter-to-total mapping, and agencies stuffing multi-version releases can decouple album units from revenue quality."}, {"id": 17, "name": "Square-Money Hold Nowcast", "vol": "I", "score": 20, "lens": "Cross-domain analogy transfer", "data": "The combination of closing betting lines (Pinnacle/The Odds API), public ticket-and-handle split percentages (Action Network, VSIN, sportsbooks' own splits pages), and final game scores \u2014 enough to compute each week whether the betting public beat the books.", "collection": "Archive closing lines and bet-split percentages for every NFL/NBA slate via The Odds API plus scrapes of Action Network and VSIN; after games settle, compute a weekly 'public P&L' \u2014 did heavily-bet favorites, overs, and popular parlay legs cash? \u2014 and cumulate it into a quarterly sportsbook hold estimate versus normal hold.", "trade": "Short DKNG/FLUT/PENN/MGM (or buy puts) into monthly state revenue releases (NJ DGE, Illinois) and quarterly earnings when the cumulated ledger shows bettor-friendly outcomes, long when the books have run hot; horizon one to six weeks.", "mechanism": "Sportsbook revenue is handle times hold, and the outcome-dependent component of hold is fully computable in public data weeks before it appears in state filings or guidance \u2014 Flutter's November 2024 profit warning after 'customer-friendly NFL results' was knowable from scores and closing lines almos", "edge": "Equity analysts model handle growth but treat hold variance as unforecastable noise, while the betting-data community computes exactly this number weekly and never trades stocks with it; the two communities don't talk.", "risk": "Parlay-mix and promo-spend assumptions inject error into the hold reconstruction, and as more quarters get pre-announced by the companies themselves the surprise window shrinks; bet-split data quality varies by book."}, {"id": 18, "name": "Call Report Amendment Autopsy", "vol": "II", "score": 20, "lens": "Filing-diff archaeology", "data": "FFIEC Central Data Repository (CDR) quarterly call reports (FFIEC 031/041/051) for the roughly 700 exchange-listed US banks, including revised resubmissions and free-text itemizations in Schedule RI-E and memo items in RC-O/RC-N.", "collection": "Pull the CDR Public Data Distribution API daily and archive every facsimile version per bank so resubmissions diff against originals; parse RI-E 'other noninterest expense' text items, RC-N past-due migration, and uninsured-deposit memo lines, flagging adverse amendments and first-appearance text items like 'litigation settlement'.", "trade": "Short single-name community and regional banks (hedged with KRE) within days of an adverse call-report amendment or a new adverse footnote item, holding 1-6 weeks into the bank's 10-Q or next earnings release.", "mechanism": "Call reports land about 30 days after quarter-end with more granularity than earnings releases, and an amendment is a quasi-restatement: it almost always precedes the same bad news reaching the 10-Q or an 8-K, so the versioned diff front-runs the documents analysts actually read.", "edge": "Bank analysts consume CDR data as point-in-time levels via vendors; nobody treats it as a versioned document stream or reads the free-text footnotes for the long tail of $200M-$2B banks with zero coverage.", "risk": "Most amendments are clerical, so the signal is sparse and needs a benign-vs-adverse taxonomy; small bank stocks are also illiquid, hard to borrow, and slow to reprice."}, {"id": 19, "name": "Warranty Fine-Print Retreat", "vol": "II", "score": 20, "lens": "Filing-diff archaeology", "data": "Manufacturer warranty booklets and warranty-terms webpages for autos, appliances, HVAC, power tools, solar inverters, and e-bikes (e.g., Hyundai/Kia powertrain pages, Generac, Carrier, SolarEdge, Whirlpool warranty PDFs).", "collection": "Run a monthly crawler over a curated list of warranty-term URLs and PDFs, backfilled with the Wayback Machine CDX API for history; diff coverage years, mileage caps, transferability, newly excluded components, and registration hurdles per product line.", "trade": "Short the manufacturer (or trade it against a competitor pair) for 2-6 weeks after a coverage retreat, positioned into the next earnings where warranty accruals surface; go long or cover when a maker extends coverage, a revealed-confidence signal from internal reliability data.", "mechanism": "Warranty terms are set by actuaries reading internal claims-frequency data outsiders never see; shortening coverage or newly excluding a specific component is a costly admission that failure rates are running hot, which later materializes as warranty-reserve builds, recalls, and margin misses.", "edge": "These changes are unannounced, live on marketing pages rather than filings, and no data vendor versions warranty language \u2014 the per-company curation is exactly the tedious, unscalable work institutions decline.", "risk": "Term changes can be driven by regulation or competitive positioning rather than reliability, and the lag from fine print to P&L can exceed a short horizon, so the trade needs an earnings catalyst to cash the signal."}, {"id": 20, "name": "Off-Cycle Audit-Partner Swap", "vol": "II", "score": 20, "lens": "Gatekeeper & service-provider behavior", "data": "PCAOB Form AP (AuditorSearch) \u2014 a downloadable database naming the engagement partner for every US public-company audit since 2017, which makes partner tenure and mid-rotation changes computable.", "collection": "Download the Form AP dataset (pcaobus.org AuditorSearch bulk CSV) on each update, compute per-issuer partner tenure, and flag partner changes occurring before the mandatory 5-year rotation clock expires \u2014 especially those coinciding with no firm change (so no Item 4.01 8-K is triggered).", "trade": "Short or buy puts on issuers with an off-cycle partner swap ahead of their next 10-K/10-Q filing date (2-8 week horizon), sized up when paired with a fiscal-year-end audit and elevated accruals; the annual-report date is the catalyst.", "mechanism": "Partners rotate off-cycle when there is an internal dispute, an independence violation, or the firm quietly benches a partner over a problem client; unlike an auditor resignation, a partner swap requires no 8-K, so the only public trace is Form AP \u2014 and the disagreement that caused it tends to surfa", "edge": "Auditor-change 8-Ks are heavily mined but partner-level churn is not: Form AP is an obscure PCAOB dataset with clunky identifiers, and computing 'off-cycle' requires reconstructing rotation clocks nobody bothers to build.", "risk": "Form AP filings lag the audit report by up to 35 days, partners also change for benign reasons (retirement, office moves), and the base rate of adverse outcomes per swap may be low \u2014 requiring conditioning variables to be tradable."}, {"id": 21, "name": "Trustee Exit Tape", "vol": "II", "score": 20, "lens": "Gatekeeper & service-provider behavior", "data": "Indenture-trustee resignations and successor-trustee appointments disclosed in 8-Ks, supplemental indentures, and press notices \u2014 particularly the appointment of default-specialist trustees (Wilmington Savings, Ankura Trust, UMB) replacing money-center banks.", "collection": "EDGAR full-text search daily for 'resignation of trustee', 'successor trustee', and supplemental-indenture exhibits; classify the incoming trustee by whether it is a known distressed-situations specialist versus a routine corporate trust bank.", "trade": "Short the stock or buy puts on leveraged issuers whose bank trustee resigns in favor of a distress-specialist trustee, holding 2-6 weeks into the covenant test, coupon date, or exchange offer that typically follows; unwind on the restructuring announcement.", "mechanism": "Bank trustees resign to shed liability precisely when they foresee a default or coercive liability-management exercise, and the distress-specialist successors are hired by creditor groups organizing for a fight \u2014 the trustee swap is the paperwork shadow of a creditor war that hasn't hit headlines.", "edge": "Trustee changes are filed as dry Item 8.01/exhibit boilerplate that neither equity screens nor news algos flag, and interpreting them requires knowing which trustees only show up for funerals \u2014 trade folklore from the restructuring bar, not a vendor ", "risk": "Some trustee shuffles follow corporate-trust business divestitures (benign M&A among trustees), and by the time equity is shortable much distress may be priced; the signal is strongest in crossover credits where equity still trades as if healthy."}, {"id": 22, "name": "Dividend Clock Slip", "vol": "II", "score": 20, "lens": "Corporate calendar & scheduling tells", "data": "Dividend declaration press releases and 8-Ks \u2014 specifically the declaration date measured against the board's historical declaration cadence (e.g., 'declares the second Tuesday after quarter close, 30 quarters running').", "collection": "Build per-company declaration-date histories from Nasdaq.com dividend history, EDGAR, and newswire archives; a daily cron flags payers whose expected declaration window has passed with silence, ranked by payout ratio, leverage, and coverage deterioration.", "trade": "Short or buy puts on flagged high-yield names (REITs, BDCs, midstream, telecom) immediately when the habitual window expires; resolution \u2014 a cut, a 'dividend review,' or a late-but-intact declaration \u2014 usually lands within 1-3 weeks.", "mechanism": "Dividend cuts come out of contentious board meetings that run past the routine calendar; the gap between the habitual declaration date and the eventual announcement is the observable shadow of that internal debate, and cuts disproportionately follow such slips, repricing the equity 10-30%.", "edge": "Income investors watch amounts and ex-dates, not the declaration timestamp against a per-board baseline; constructing those baselines is tedious archival work with no commercial feed.", "risk": "Boards occasionally shift cadence for benign reasons (calendar reshuffles, merger integration), and in broad selloffs the cut is priced before the window even expires."}, {"id": 23, "name": "Top-Mover Carousel", "vol": "II", "score": 20, "lens": "Retail herd telemetry", "data": "The algorithmic 'Top Movers' and 'Trending' carousels inside Coinbase and Robinhood apps, whose entry rules (24h percent change thresholds) trigger push notifications and home-screen placement to tens of millions of retail users \u2014 a mechanical attention amplifier with observable inputs.", "collection": "Reconstruct carousel membership in real time from Coinbase's public markets API and Robinhood's quote endpoints by replicating the ranking math (24h movers among supported assets), and verify against periodic scripted app scrapes; log entry and exit timestamps per asset.", "trade": "Buy perpetual futures (or spot) on mid-cap coins at the moment they newly qualify for the carousel \u2014 the push-notification herd arrives over the next 2-12 hours \u2014 then reverse to short the same names 1-2 days after entry as attention-driven buying exhausts and mean-reverts.", "mechanism": "Placement in the app UI causes flow, not just correlates with it: a coin crossing the mover threshold gets broadcast to millions of users whose purchase friction is one tap, generating a second wave of buying mechanically after the initial move, followed by the well-documented reversal of attention-", "edge": "The trigger is a deterministic function of public price data \u2014 you can compute carousel entry seconds after it happens, before the notification wave lands \u2014 yet crypto quant desks model order flow, not the retail app UI that generates it.", "risk": "Coinbase/Robinhood can change ranking rules or throttle notifications silently, breaking the replication; in thin coins the initial threshold-crossing move may itself be manipulation designed to exploit the same carousel, putting you in the pump's ex"}, {"id": 24, "name": "Performance-Bond Spiral Forecaster", "vol": "II", "score": 20, "lens": "Collateral & funding-stress micro-signals", "data": "CME Clearing performance-bond (margin) change advisories and LME margin circulars, combined with the clearinghouses' published margin-model mechanics (SPAN/SPAN2 volatility lookbacks) that make hikes forecastable from realized vol.", "collection": "Scrape the CME Clearing Advisories page (daily notices with per-contract margin changes and effective dates) and lme.com circulars; in parallel run a shadow SPAN calculation on settlement prices to forecast which contracts are one to two days from a margin-coverage breach that will compel a hike.", "trade": "In a trending, open-interest-heavy contract (nickel, natgas, cocoa), position with the trend into a forecast margin hike and hold through the 1-3 sessions after the effective date as undercapitalized holders cut, then fade once open interest has flushed. Futures and futures options, 1-10 day horizon", "mechanism": "A margin hike is a synchronized capital call on every open position with a known effective date; weak hands must post or liquidate, so the hike mechanically extends the move that caused it, and the subsequent open-interest drop removes the forced flow, setting up the reversal leg.", "edge": "The advisories are public PDFs with effective dates that almost no one parses systematically, and virtually nobody runs the margin model forward to trade the hike before it is announced \u2014 institutions treat clearing margin as an operations problem, n", "risk": "Clearinghouses sometimes hike pre-emptively in calm markets, producing no forced flow, and the signal is confounded with the volatility spike itself \u2014 separating margin-flow alpha from simple momentum requires careful open-interest conditioning."}, {"id": 25, "name": "Leverage-Bracket Diff Bot", "vol": "II", "score": 20, "lens": "Collateral & funding-stress micro-signals", "data": "Crypto exchanges' per-token risk parameters: Binance/Bybit/OKX futures leverage brackets, collateral haircut tables, and margin-tier announcements, which get cut on specific tokens with a stated effective timestamp when the exchange's risk desk sees dangerous concentration.", "collection": "Poll Binance's /fapi/v1/leverageBracket and collateral-ratio endpoints, OKX's position-tier tables, and Bybit's risk-limit pages daily via API, diffing parameters per token; parse exchange announcement pages for scheduled collateral-ratio reductions and removals of tokens from cross-margin collateral.", "trade": "Short the affected token's perpetual between announcement and effective time, when accounts above the new tiers are force-reduced, then fade after the liquidation cluster prints; hours-to-days horizon.", "mechanism": "Exchange risk desks see position concentration and order-flow toxicity no outsider can; a leverage or collateral cut is simultaneously their leaked verdict and a mechanical deleveraging schedule, because accounts exceeding the new caps are auto-reduced or margin-called at the published time.", "edge": "The parameters sit in lightly-authenticated API endpoints that traders consult only for their own orders \u2014 treating the cross-sectional risk-parameter surface as a signal feed is still niche, and every exchange formats it differently, deterring syste", "risk": "Exchanges sometimes cut leverage market-wide for regulatory reasons carrying no single-name information, and front-running liquidations in thin alts risks becoming the exit liquidity if insiders traded the announcement first."}, {"id": 26, "name": "337 Target-Date Clock", "vol": "II", "score": 20, "lens": "Legal-outcome handicapping", "data": "The USITC's EDIS filing system for Section 337 investigations: statutory target dates, ALJ initial-determination notices, Commission determinations to review, and target-date extension orders \u2014 a fully dated pipeline toward import exclusion orders.", "collection": "Use the EDIS REST API (edis.usitc.gov, free registration) to poll every active 337 investigation; parse Federal Register notices for target dates; alert on the short-form 'notice of initial determination' which posts on EDIS hours before the reasoned opinion or any press coverage, and calendar the 60-day Presidential-review windows after exclusion orders.", "trade": "Trade respondents whose US revenue rides on the accused imports (consumer electronics, e-vapor, robotics small caps) and complainant licensors (a Sonos/Google-type pattern) intraday on ID-notice day, plus buy straddles into statutorily scheduled determination dates. Horizon: intraday to the 60-day r", "mechanism": "An exclusion order is a binary revenue kill-switch for the respondent's US imports, and the 337 process publishes its own calendar by statute; the ID notice states violation/no-violation in one line, so direction is machine-readable minutes after posting while equity markets often take hours to reac", "edge": "ITC practice is a tiny specialist bar; equity desks watch district-court patent verdicts but routinely miss EDIS postings, and the API is clunky enough (session tokens, inconsistent metadata) to deter casual use.", "risk": "Target dates slip via extension orders, remedies are frequently narrowed or mooted by design-arounds and Presidential disapproval is rare but possible, so the binary you handicapped can dissolve into a non-event."}, {"id": 27, "name": "Settlement Choreography Tape", "vol": "II", "score": 20, "lens": "Legal-outcome handicapping", "data": "The procedural ballet that precedes large settlements: Rule 53 special-master and mediator appointment orders, magistrate settlement-conference scheduling, joint motions to stay deadlines, and abrupt 'trial vacated' minute entries in MDLs and bet-the-company single-stock cases.", "collection": "Set CourtListener docket alerts and parse PACER RSS minute entries for a controlled vocabulary ('appointing settlement master', 'referred to mediation', 'settlement conference set', 'trial date vacated', 'stay pending settlement discussions') across a watchlist of ~200 dockets tied to public defendants; the 3M earplug and Roundup MDLs provide the training corpus.", "trade": "Buy the defendant (Bayer ADR, 3M, J&J, GSK-type overhang names) and sell its elevated put skew when choreography entries cluster, since settlement removes tail risk at a knowable-ish number; fade if talks collapse (conference held, then new trial dates set). Horizon: one to six weeks.", "mechanism": "Courts cannot schedule mediation or vacate trials in secret \u2014 the machinery of settling must be docketed days-to-weeks before a term sheet leaks; because litigation overhangs trade at a fear discount with fat put skew, the procedural tell predicts both the equity pop and the vol crush of an announce", "edge": "Legal newsletters report these entries days later in prose; nobody converts minute-entry semantics into a timestamped cross-docket feed, because it requires curating dockets and reading procedural jargon rather than buying a data product.", "risk": "Many mediations are court-ordered formalities that fail, and sophisticated defendants know the tell \u2014 a mediator appointment can itself be negotiating theater, so the signal decays into noise exactly in the highest-profile cases where the payoff is b"}, {"id": 28, "name": "DART Gap Runner", "vol": "II", "score": 20, "lens": "Disclosure-latency arbitrage", "data": "Korea's DART regulatory filing system (Financial Supervisory Service), where chaebol banks, telecoms, and industrials must file material disclosures in Korean during Seoul afternoon hours \u2014 after the KRX close but a full night before their US-listed ADRs open.", "collection": "Poll the free OpenDART REST API (opendart.fss.or.kr) every minute from 15:00-19:00 KST for new filings tagged material (capital raises, large shareholder changes, merger decisions, earnings revisions), machine-translate and classify with an LLM, and flag tickers with US ADRs (KB, SHG, KEP, PKX, SKM, KT, LPL).", "trade": "Buy or short the corresponding NYSE ADR in US pre-market or at the open, exiting within 1-2 sessions once English-language wires and the next Seoul session catch up; use ADR options on the liquid names (PKX, KB) for capital-raise dilution shorts.", "mechanism": "The information is legally public at filing time in Korea, but English translations and wire coverage lag hours to a day, and the local market that would price it is closed \u2014 so the ADR trades a full US session against a stale price until Seoul reopens.", "edge": "Requires Korean-language parsing, KST-hours operation, and ADR mapping \u2014 a fragmented, unglamorous pipeline; global desks arb the big index names but ignore second-tier ADRs where the latency is longest.", "risk": "ADR liquidity is thin so slippage eats the move on smaller names, and specialist Korea funds or the ADR depositary desks may already fade the most obvious filings, leaving only ambiguous ones."}, {"id": 29, "name": "First-Generic Flash", "vol": "II", "score": 20, "lens": "Disclosure-latency arbitrage", "data": "FDA's Drugs@FDA approval database and the openFDA drugsfda endpoint, where ANDA approvals \u2014 including the first generic against a branded franchise \u2014 post within a day of action, frequently before the generic filer's press release and before the branded incumbent acknowledges anything.", "collection": "Poll the openFDA drugsfda API and the FDA 'First Generic Approvals' page daily, join new ANDA approvals to the Orange Book to identify which branded NDA loses exclusivity, and map the branded product to its revenue share of the incumbent's income statement using 10-K product-line disclosures.", "trade": "Buy puts on the branded mid-cap pharma (where a single franchise is >15% of revenue) and optionally go long the approved generic maker (Amneal, Hikma ADR, TEVA), holding days to two weeks as sell-side updates erosion models.", "mechanism": "First-generic entry mechanically triggers 80-90% price erosion of the branded molecule over subsequent quarters; the approval is public in the database hours-to-days before wires cover it, so the incumbent's price is stale in the gap.", "edge": "Generic approvals are boring, high-volume, and fragmented across hundreds of ANDAs, so no headline algo watches the raw database \u2014 specialist pharma desks track the big cliffs but mid-cap single-product stories slip through.", "risk": "Approval does not equal launch \u2014 patent settlements and 30-month stays can delay commercialization for years, and the biggest loss-of-exclusivity dates are so well telegraphed that the approval itself is a non-event."}, {"id": 30, "name": "EDIS Exclusion-Order Wire", "vol": "II", "score": 20, "lens": "Disclosure-latency arbitrage", "data": "The US International Trade Commission's EDIS docket system for Section 337 investigations, where new import-ban complaints, ALJ initial determinations, and Commission final notices post before newswire coverage \u2014 with statutory target dates docketed months in advance.", "collection": "Register a free EDIS account and poll edis.usitc.gov for new 337 complaints and determinations daily, parse the PDFs for complainant/respondent tickers and accused products, and build a calendar from the docketed target dates for initial and final determinations.", "trade": "Buy the small-cap complainant (patent licensors and one-product hardware firms historically pop on favorable IDs) or short pure-play respondents on adverse determinations within hours of the EDIS post, holding days; pre-position with options into the docketed decision dates.", "mechanism": "A 337 exclusion order is an import ban \u2014 an existential remedy for a respondent's US revenue and a royalty-forcing lever for a complainant \u2014 and the determination text hits EDIS before the parties' press releases, so the docket is the primary source trading against stale prices.", "edge": "EDIS is a login-gated, PDF-heavy 1990s-era system that mainstream news scrapes poorly; IP litigation funds watch their own cases but no one systematically trades the whole 337 calendar including small-cap complainants.", "risk": "Determinations are frequently stayed, settled, or Presidentially reviewed before economic effect, and mega-cap respondents shrug off single-product bans, so the tradable set is limited to concentrated small names."}, {"id": 31, "name": "Fintech Vintage X-Ray", "vol": "II", "score": 20, "lens": "Structured-finance small print", "data": "Marketplace and consumer-loan ABS monthly performance: trustee-report charge-off and delinquency curves for Upstart (UPST securitization shelves), Affirm, Pagaya, OneMain, LendingClub deals, summarized monthly in KBRA's Consumer Loan Indices and per-deal surveillance.", "collection": "Compile per-vintage monthly loss curves from KBRA's free index publications, Finsight deal pages, and dv01/Intex summaries quoted in rating-agency reports; align each sponsor's securitized vintages to the fiscal quarter they will hit the P&L as provisions or fair-value marks.", "trade": "Position in UPST, AFRM, OMF, LC, PGY equity and options 1-3 weeks before earnings based on whether the freshest securitized vintages are tracking above or below the loss curves embedded in guidance; pair long-best vs short-worst originator on divergence.", "mechanism": "These lenders' securitized pools are large representative samples of the very originations that drive their fair-value marks and provisions, but the trust data prints monthly while earnings print quarterly; a vintage running hot in month two of the quarter arithmetically forces a mark-down or provis", "edge": "The retail-heavy shareholder bases of UPST/AFRM demonstrably do not read ABS surveillance, and even institutional holders rarely map vintage curves to fair-value accounting mechanics; the data is free but requires stitching agencies, trustees, and fi", "risk": "Sponsors sell whole loans to private credit funds off-securitization, so the securitized sample can become adversely or favorably selected relative to the retained book, quietly breaking the mapping."}, {"id": 32, "name": "Baby-Bond Call Latency", "vol": "II", "score": 20, "lens": "Corporate-action mechanics", "data": "Full and partial redemption notices for $25-par exchange-traded baby bonds and preferreds, published via 8-Ks, trustee notices, and DTCC notices, against stale quotes in these retail-held issues.", "collection": "Stream EDGAR 8-Ks filtered for 'notice of redemption'/'notice of full redemption' mapped to a hand-built table of listed $25-par tickers (seed from QuantumOnline/Innovative Income lists); watch DTCC's public important-notices page as a second channel.", "trade": "Within minutes of a notice, sell or short the called issue wherever it trades above call price plus accrued (it must converge to par by the stated 30-day call date) and buy discounted sister issues from the same issuer likely to be called next; horizon days.", "mechanism": "The redemption price and date are contractual certainties once noticed, but the holder base is retail investors in illiquid listed debt who reprice over days, leaving above-par quotes that decay deterministically to par.", "edge": "Individual issues are usually under $100M \u2014 beneath any desk's attention \u2014 and the notices are scattered across trustees, 8-Ks, and DTCC rather than a single feed, so speed plus a ticker-mapping table is the entire moat.", "risk": "Borrow in tiny preferreds is often unavailable (limiting the short side to positions you already hold), and partial calls by lot or make-whole provisions blur the convergence target."}, {"id": 33, "name": "13E-3 Cash-Out Harvest", "vol": "II", "score": 20, "lens": "Corporate-action mechanics", "data": "SC 13E-3 filings for going-private reverse/forward split squeeze-outs, which publish the exact cash price at which holders below a share threshold will be mandatorily bought out.", "collection": "Monitor the EDGAR daily index for new SC 13E-3s and the companion PRE/DEF 14A; parse the cash-out price per pre-split share, the threshold (e.g., holders of fewer than 5,000 shares), and the meeting/effective timetable.", "trade": "Buy sub-threshold positions in names trading below the announced cash-out price and hold to the effective date; optionally add a larger common position when the discount overstates deal-break risk in an insider-controlled vote; multi-week horizon.", "mechanism": "The company itself publishes a mandatory purchase price for small positions, so the discount is pure completion risk on a transaction the controlling insider both proposed and has the votes to pass \u2014 an unusually clean dated convergence.", "edge": "The threshold caps position size, making the trade structurally uninvestable for funds and perfect for individuals with multiple accounts; 13E-3s are among the least-watched filing types on EDGAR.", "risk": "Boards can re-cut the cash-out price or ratio before the vote, timetables slip for months, and an abandoned deal leaves you holding an illiquid controlled micro-cap."}, {"id": 34, "name": "Rotor Count (Gulf of Mexico crew-helicopter ADS-B)", "vol": "I", "score": 19, "lens": "Physical-world sensing & sensor exhaust", "data": "Bristow, PHI, and ERA helicopters shuttling crews to Gulf of Mexico deepwater platforms transmit ADS-B, visible in unfiltered feeds; sortie tempo measures platform manning, evacuation pace before hurricanes, and re-manning speed after.", "collection": "Query the ADS-B Exchange API for the registered offshore-helicopter fleets (tail registries are public FAA data), geofence known helideck coordinates from BOEM platform databases, and count daily sorties per platform cluster.", "trade": "Henry Hub and WTI futures intraday-to-one-week around storm events, plus offshore-weighted producers (MUR, TALO); the trade is fading or front-running BSEE's lagged shut-in percentage releases.", "mechanism": "Crews physically leave before production shuts in and physically return before it restarts; helicopter sorties therefore lead BSEE shut-in statistics by 12-48 hours, and those statistics mechanically move storm-period gas and crude pricing.", "edge": "Corporate-jet ADS-B is a crowded trade, but rotary-wing offshore logistics is untouched - it requires curating helicopter registries and helideck coordinates, tedious work with no vendor product.", "risk": "Terrestrial ADS-B coverage degrades far offshore, so distant platforms drop out unless you buy satellite ADS-B; operators also reposition helicopters for maintenance, injecting non-demand noise."}, {"id": 35, "name": "Upset Detector (TCEQ emission-event filings + PurpleAir)", "vol": "I", "score": 19, "lens": "Physical-world sensing & sensor exhaust", "data": "Texas requires refinery and petrochemical operators to file air emission event (upset/flaring) reports to the public TCEQ Air Emission Event Report Database within 24 hours, often within hours of a unit trip; crowd-sourced PurpleAir particulate sensors near fence lines spike during the same upsets.", "collection": "Scrape the TCEQ AEE search interface on a 15-minute loop, parse unit names and emission volumes against a hand-built ontology of FCC/crude/coker units by refinery, and cross-confirm timing with PurpleAir API PM2.5 anomalies at sensors within 3 km of each plant.", "trade": "RBOB and ULSD crack spreads and refiner equities (VLO, MPC, PBF) intraday-to-days: long cracks/short the affected refiner when a large FCC or crude-unit trip is filed before newswires pick it up.", "mechanism": "An unplanned outage at a large Gulf Coast unit removes product supply, mechanically widening cracks once IIR or Reuters reports it; the regulatory filing plus sensor confirmation is the same information hours earlier in the chain.", "edge": "The database is an obscure, clunky state web app that requires refinery-unit domain knowledge to interpret; the professional channel (IIR phone surveys) is the known product, while the raw upstream regulatory exhaust goes largely unwatched in real ti", "risk": "Filing timeliness varies - sometimes Reuters energy reporters or refinery-town Facebook groups beat the filing - and most events are immaterial, so without good unit-size filtering the strategy drowns in false positives."}, {"id": 36, "name": "Channel Fog (LNG-channel met-ocean halts)", "vol": "I", "score": 19, "lens": "Physical-world sensing & sensor exhaust", "data": "NOAA NDBC buoys, NWS marine dense-fog advisories, and Gulf pilot-association/port condition notices (Houston, Sabine, Aransas pilots suspend boardings) together signal closures of the ship channels serving Sabine Pass, Corpus Christi, and Freeport LNG.", "collection": "Poll the NDBC realtime API for visibility/swell at buoys off each channel, scrape NWS marine advisories and the pilots' publicly posted boarding-suspension notices, and flag multi-day winter fog regimes blocking LNG tanker movements.", "trade": "Front-month Henry Hub futures/options and the HH-TTF spread, intraday to one week: fade HH strength (or buy it on reopening) when loadings are physically halted and gas backs up into the domestic market.", "mechanism": "LNG exports are ~15% of US gas demand; each day of suspended pilot boardings strands cargoes, cuts terminal feedgas intake, and adds supply to the domestic balance - a mechanical, physics-driven demand shock that repeats every fog season.", "edge": "Everyone watches hurricanes; almost nobody systematizes the smaller-but-frequent winter fog closures, and the pilots' notices are an obscure maritime channel that precedes the feedgas-flow data most desks wait for.", "risk": "Feedgas nomination data is increasingly watched, compressing the lead time to hours; terminals also recover quickly by re-sequencing berths, so only multi-day fog regimes move the balance materially."}, {"id": 37, "name": "Wallet-Freeze Basis Trade", "vol": "I", "score": 19, "lens": "Human digital-behavior exhaust", "data": "Exchange-published per-asset deposit/withdrawal suspension flags and wallet-maintenance notices (Binance capital-config endpoint, Coinbase/Kraken statuspage feeds, exchange announcement pages).", "collection": "Poll Binance's authenticated /sapi/v1/capital/config/getall (free account API key) for depositEnable/withdrawEnable flags per asset every minute, plus the statuspage.io JSON feeds of major exchanges; alert on newly suspended deposits for any listed token.", "trade": "Intraday-to-multi-day trades in the affected token's perp-vs-spot basis and cross-venue spreads: fade the venue premium that builds while deposits are frozen, sized to collapse at the announced re-enable time.", "mechanism": "When deposits are suspended, arbitrageurs cannot replenish sell-side inventory on that venue, so idiosyncratic buying pushes a mechanical local premium; re-enabling deposits restores arbitrage and the premium collapses on schedule.", "edge": "The flags are technically public but buried in per-asset config endpoints nobody watches, and each event is too small and too frequent for institutional capital to bother systematizing.", "risk": "A suspension sometimes signals a hack or insolvency rather than maintenance, in which case the 'premium' is a fair discount and fading it means picking up pennies in front of a collapse."}, {"id": 38, "name": "Sponsor-Read Ledger", "vol": "I", "score": 19, "lens": "Human digital-behavior exhaust", "data": "SponsorBlock's open crowdsourced database of sponsor-segment timestamps across YouTube, joined to video transcripts to identify which advertiser bought each read.", "collection": "Download the freely mirrored SponsorBlock DB dumps (sponsor.ajay.app), pull auto-transcripts for flagged segments via yt-dlp/YouTube API, and run entity extraction on segment text to produce a weekly view-weighted influencer-ad-spend index per brand.", "trade": "Public advertisers dependent on creator marketing \u2014 HelloFresh (HFG.DE), DraftKings (DKNG), Squarespace (SQSP), Duolingo (DUOL) \u2014 into earnings on 2-6 week horizons when sponsor-read share inflects, signaling customer-acquisition-spend and new-customer surprises.", "mechanism": "Influencer sponsorships are booked weeks ahead and scale directly with customer-acquisition budgets, so a surge or collapse in a brand's share of sponsor reads leads both marketing-expense lines and new-customer adds reported the following quarter.", "edge": "The dataset only exists because ad-skipping volunteers built it, and nobody has joined it to transcripts to reconstruct an ad-spend panel \u2014 it is a free, timestamped census of a spend channel card panels cannot see.", "risk": "Attribution is noisy (multi-brand reads, ambiguous coupon codes), and SponsorBlock coverage skews toward tech-adjacent channels, under-sampling beauty and lifestyle verticals."}, {"id": 39, "name": "Roblox Live Census", "vol": "I", "score": 19, "lens": "Human digital-behavior exhaust", "data": "Roblox's own public games API, which exposes live concurrent-player counts per experience with no authentication.", "collection": "Poll games.roblox.com/v1/games for the top ~2,000 universe IDs every 10 minutes, aggregate into platform-wide CCU weighted by each experience's monetization tier, and calibrate the integral against Roblox's disclosed DAU/engagement-hours/bookings history.", "trade": "RBLX into earnings over 2-6 weeks, plus same-day trades around monthly-metrics releases when the CCU-integral nowcast disagrees with consensus bookings.", "mechanism": "Bookings equal engagement-hours times monetization rate, and platform-native live player counts integrate directly to engagement-hours with zero panel bias, so the nowcast tracks the disclosed metric almost mechanically.", "edge": "Institutions buy panel-based estimates (Sensor Tower et al.) that everyone shares and that miss web/console play, while the platform's own free telemetry requires maintaining a universe-ID census and 24/7 polling that nobody bothers to run.", "risk": "Roblox could gate the endpoint, and CCU misses ARPU mix shifts (aging user base, advertising revenue), so an engagement-flat but monetization-hot quarter escapes the model."}, {"id": 40, "name": "Cooling-Off Clock (NMB/FMCS Strike Countdown)", "vol": "I", "score": 19, "lens": "Labor-market micro-signals", "data": "National Mediation Board case dockets and 'release from mediation' determinations for airlines and railroads, plus FMCS 30-day dispute notices (F-7 filings) for general industry contract expirations.", "collection": "Scrape the NMB's weekly determinations page and mediation case docket (nmb.gov) and FMCS's public notice data; join against a hand-built calendar of amendable dates for pilot, flight-attendant, and rail-craft contracts to compute exact days-until-legal-strike for each carrier.", "trade": "Buy 2-6 week puts or put spreads on the specific carrier (AAL, UAL, LUV, ALK, UNP, CSX, NSC) when a release from mediation starts the statutory 30-day clock; unwind into the deadline as either a strike or a tentative agreement resolves the binary.", "mechanism": "Under the Railway Labor Act a strike is legally impossible until mediation release plus 30 days, so the docket converts diffuse labor tension into a precisely dated catalyst; realized and implied volatility mechanically migrate toward that date, and any actual stoppage at a network carrier or Class ", "edge": "The NMB publishes in an obscure weekly format that almost nobody outside labor lawyers reads, and the two-statute patchwork (RLA vs Taft-Hartley) deters generalist quants; airline options desks typically only price the risk after a strike-authorizati", "risk": "The vast majority of clocks end in a tentative agreement or a Presidential Emergency Board, so the trade must be structured as cheap convexity into a dated event rather than a directional strike bet, and premium bleed is the base case."}];

const TRIAGE_SCHEMA = {
  type: 'object', required: ['results'],
  properties: { results: { type: 'array', items: {
    type: 'object', required: ['id','name','decision','data_exists','latency','already_priced','reason'],
    properties: {
      id: { type: 'integer' }, name: { type: 'string' },
      decision: { type: 'string', description: 'ADVANCE / KILL' },
      data_exists: { type: 'string', description: 'Does the named data source actually exist and is it publicly accessible? Cite what you verified.' },
      latency: { type: 'string', description: 'How fast does this data publish vs when the market learns the same thing?' },
      already_priced: { type: 'string', description: 'Is the market already reacting to this before you could act?' },
      reason: { type: 'string', description: 'Why advance or kill, in 1-3 sentences' },
      biggest_doubt: { type: 'string' },
    } } } },
}

const EDGE_SCHEMA = {
  type: 'object',
  required: ['name','verdict','edge_case','against_case','who_is_on_other_side','frictions','capacity','net_edge_estimate','confidence'],
  properties: {
    name: { type: 'string' },
    verdict: { type: 'string', description: 'REAL-EDGE / MARGINAL / LIKELY-ILLUSORY / NO-EDGE' },
    edge_case: { type: 'string' },
    against_case: { type: 'string' },
    who_is_on_other_side: { type: 'string' },
    frictions: { type: 'string', description: 'Concrete cost stack with numbers: spread, commissions, slippage, options width, borrow if short' },
    capacity: { type: 'string' },
    event_frequency: { type: 'string', description: 'How many tradeable events per year, realistically' },
    net_edge_estimate: { type: 'string' },
    data_pipeline: { type: 'string', description: 'Exact endpoints/sources and update cadence needed to run it' },
    confidence: { type: 'string' },
  },
}

const RED_SCHEMA = {
  type: 'object', required: ['target','kill_shots','survives'],
  properties: {
    target: { type: 'string' },
    kill_shots: { type: 'array', items: { type: 'object', required: ['attack','severity'],
      properties: { attack: { type: 'string' }, severity: { type: 'string' }, rebuttal_possible: { type: 'string' } } } },
    survives: { type: 'string' },
    required_evidence: { type: 'string' },
  },
}

const PLAYBOOK_SCHEMA = {
  type: 'object', required: ['playbooks','killed','allocation'],
  properties: {
    playbooks: { type: 'array', items: {
      type: 'object', required: ['name','verdict','universe','signal','entry','expression','sizing','exit','costs','first_test'],
      properties: {
        name: { type: 'string' }, verdict: { type: 'string' }, universe: { type: 'string' },
        signal: { type: 'string' }, entry: { type: 'string' }, expression: { type: 'string' },
        sizing: { type: 'string' }, exit: { type: 'string' }, costs: { type: 'string' },
        monitoring: { type: 'string' }, first_test: { type: 'string' },
      } } },
    killed: { type: 'array', items: { type: 'object', required: ['name','why'],
      properties: { name: { type: 'string' }, why: { type: 'string' } } } },
    allocation: { type: 'string' },
    build_order: { type: 'array', items: { type: 'string' } },
  },
}

const chunk = (arr, size) => { const o=[]; for (let i=0;i<arr.length;i+=size) o.push(arr.slice(i,i+size)); return o }

// ---------- Phase 1: Triage ----------
phase('Triage')
const groups = chunk(CANDIDATES, 4)
const triaged = await parallel(groups.map((grp, gi) => () =>
  agent(`You are a skeptical trading-desk analyst screening brainstormed signal ideas for whether they could EVER be traded profitably. You have web access — load WebSearch/WebFetch via ToolSearch ("select:WebSearch,WebFetch") and actually verify the key claims. Do not invent sources.

For EACH of the ${grp.length} ideas below, decide ADVANCE or KILL. Kill an idea if any of these is true:
- The named data source does not exist, is not public, or is not obtainable at the stated cadence.
- The information reaches the market (newswire, company PR, ordinary news) at the same time or sooner, so there is no informational lead.
- The implied move is too small or too rare to cover spread and commissions in the named instruments.
- The instruments are untradeable for a small trader (no options, illiquid, foreign-only access).
- The signal is already a commercial product or widely scraped.
ADVANCE only ideas where a genuine, timely informational lead plausibly exists AND the trade is executable by a small trader.

Be strict — killing most is the expected outcome and is a useful result. Verify data sources by actually searching for them.

IDEAS:
${JSON.stringify(grp, null, 1)}

Return one result object per idea via structured output.`,
    { label: `triage:${gi+1}`, phase: 'Triage', schema: TRIAGE_SCHEMA })
))

const allTri = triaged.filter(Boolean).flatMap(t => t.results || [])
const advanced = allTri.filter(r => /ADVANCE/i.test(r.decision || ''))
log(`Triage: ${allTri.length} screened, ${advanced.length} advanced, ${allTri.length-advanced.length} killed`)

const byId = {}
for (const c of CANDIDATES) byId[c.id] = c
const survivors = advanced.map(a => ({ ...byId[a.id], triage: a })).filter(s => s.name).slice(0, 14)
log(`Refereeing ${survivors.length}: ${survivors.map(s=>s.name).join(' | ')}`)

// ---------- Phase 2: Referee ----------
phase('Referee')
const refs = await parallel(survivors.map((s) => () =>
  agent(`You are a hard-nosed buy-side risk officer determining whether a REAL, NET-OF-COST, EXPLOITABLE edge exists for a small trader — not merely whether a statistical relationship might exist. Web access available (ToolSearch -> WebSearch/WebFetch). Verify every number you can; flag anything unverified. Do not fabricate citations, fees, or event counts.

IDEA: ${s.name}   (brainstorm score ${s.score}/30, lens: ${s.lens})
DATA: ${s.data}
COLLECTION: ${s.collection}
TRADE: ${s.trade}
MECHANISM: ${s.mechanism}
CLAIMED EDGE: ${s.edge}
STATED RISK: ${s.risk}
TRIAGE NOTES: ${s.triage.reason} | latency: ${s.triage.latency} | already priced: ${s.triage.already_priced}

Do the work: (1) confirm the data source, its exact publication cadence and latency, and whether a newswire/company release beats it; (2) estimate how many genuinely tradeable events occur per year; (3) estimate the typical move size in the named instruments when the event fires; (4) build the real cost stack (bid-ask on those specific names, commissions, options spread and IV if options are used, borrow if short, slippage); (5) state who is on the other side; (6) estimate capacity; (7) judge whether the net expectancy is plausibly positive and by how much.

Verdict NO-EDGE or LIKELY-ILLUSORY is a valuable answer. Return via structured output.`,
    { label: `referee:${(s.name||'').slice(0,22)}`, phase: 'Referee', schema: EDGE_SCHEMA })
))
const goodRefs = refs.filter(Boolean)
log(`Referee verdicts: ${goodRefs.map(r=>`${(r.name||'').slice(0,18)}=${r.verdict}`).join(', ')}`)

// ---------- Phase 3: Red team ----------
phase('RedTeam')
const rank = v => ({'REAL-EDGE':0,'MARGINAL':1,'LIKELY-ILLUSORY':2,'NO-EDGE':3}[(v||'').toUpperCase()] ?? 2)
const ranked = goodRefs.slice().sort((a,b)=>rank(a.verdict)-rank(b.verdict))
const targets = (ranked.filter(r=>/REAL-EDGE|MARGINAL/i.test(r.verdict||'')).slice(0,4).length
  ? ranked.filter(r=>/REAL-EDGE|MARGINAL/i.test(r.verdict||'')).slice(0,4)
  : ranked.slice(0,3))
const reds = await parallel(targets.map((t) => () =>
  agent(`You are a red-team quant paid to DESTROY a proposed trading strategy before capital is risked. Web tools available.

TARGET: ${t.name}
PROPONENT CASE: ${(t.edge_case||'').slice(0,1200)}
CLAIMED NET EDGE: ${(t.net_edge_estimate||'').slice(0,600)}
CLAIMED FRICTIONS: ${(t.frictions||'').slice(0,800)}
EVENT FREQUENCY: ${(t.event_frequency||'').slice(0,300)}

Attack on every axis: (1) is the informational lead real, or does a wire/company release actually beat it; (2) is the sample of events so small that the apparent edge is unfalsifiable noise; (3) do frictions exceed the gross move; (4) is anyone already automating this (vendors, funds, retail scrapers); (5) does the mechanism actually hold, or are there confounds that break the causal chain; (6) is it executable in size or capacity-dead. Rate each attack fatal/serious/manageable and state honestly whether rebuttal is possible. Then state what MUST be true for it to work. Return via structured output.`,
    { label: `red:${(t.name||'').slice(0,20)}`, phase: 'RedTeam', schema: RED_SCHEMA })
))
log(`Red team complete: ${reds.filter(Boolean).length}`)

// ---------- Phase 4: Playbook ----------
phase('Playbook')
const refD = goodRefs.map(r=>`### ${r.name}
VERDICT ${r.verdict} (conf ${r.confidence})
net edge: ${r.net_edge_estimate}
frequency: ${r.event_frequency||''}
frictions: ${r.frictions}
other side: ${r.who_is_on_other_side}
capacity: ${r.capacity}
pipeline: ${r.data_pipeline||''}`).join('\n\n')
const redD = reds.filter(Boolean).map(r=>`### RED TEAM ${r.target}
survives: ${r.survives}
attacks: ${(r.kill_shots||[]).map(k=>`[${k.severity}] ${k.attack}`).join(' | ')}
needed evidence: ${r.required_evidence}`).join('\n\n')
const killD = allTri.filter(r=>!/ADVANCE/i.test(r.decision||'')).map(r=>`- ${r.name}: ${r.reason}`).join('\n')

const pb = await agent(`You are the portfolio manager making the final call on a catalog of brainstormed trading signals. Write EXECUTABLE playbooks ONLY for ideas that genuinely deserve capital or a forward test, and explicitly list what you are killing.

Be honest above all: if only two or three survive out of forty, say so plainly. A short list of real playbooks beats a long list of fake ones. Respect the red team — if an attack is fatal and unrebutted, do not write a playbook pretending otherwise.

Each playbook needs: exact universe, exact signal computation and data endpoint with cadence, entry trigger and order type, precise instrument (shares/options with tenor), sizing and concentration limits, exit, expected all-in cost per round trip, monitoring for decay, and 'first_test' = the cheapest experiment that would validate or kill it before risking size, with a specific success criterion.

The 'killed' list should cover both triage kills and referee/red-team kills, each with a one-line reason. 'allocation' must say what NOT to fund.

REFEREE VERDICTS:
${refD}

RED TEAM:
${redD}

TRIAGE KILLS:
${killD}

Return via structured output.`,
  { label: 'playbook', phase: 'Playbook', schema: PLAYBOOK_SCHEMA })

return {
  triage: allTri,
  advancedCount: advanced.length,
  referee: goodRefs,
  redteam: reds.filter(Boolean),
  playbook: pb,
}
